      id: ++s.did, seq: batch.seq, topic: tp.id, label: tp.label || '', a: { k: S[0].k, id: S[0].id, n: S[0].name, t: S[0].team ? S[0].team.id : null }, b: { k: S[1].k, id: S[1].id, n: S[1].name, t: S[1].team ? S[1].team.id : null },
