      if (u && u.k === 'c' && u.t) { const t = getTeam(u.t); if (t) return teamAvatarMark(t); }
      if (u && u.k === 'm' && u.t) { const t = getTeam(u.t); if (t && t.manager) return managerAvatarMark(t.manager, 36); }
